dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "tissue",
      "label": "Tissue",
      "type": "input",
      "display": "false"
    }
  ],
  "single search": {
    "search instruction": "Search gene or disease",
    "search parameters": [
      {
        "parameter": "gene",
        "values": "kp genes",
        "target page": {
          "label": "Search Gene",
          "page id": "kc_entity_gene",
          "entity parameter": "entity",
          "entity": "gene"
        }
      },
      {
        "parameter": "disease",
        "data point": {
          "type": "api",
          "url": "https://hugeampkpncms.org/rest/directcsv?id=mondo_disease_list",
          "data type": "json",
          "data wrapper": [
            0,
            "field_data_points"
          ]
        },
        "target page": {
          "label": "Search disease",
          "page id": "kc_entity_disease",
          "entity parameter": "entity",
          "entity": "disease"
        }
      },
      {
        "parameter": "protein",
        "data point": {
          "type": "api",
          "url": "https://cfde.hugeampkpnbi.org/api/bio/keys/exrna-rbp-counts/1?columns=rbp",
          "data type": "json",
          "data wrapper": [
            "keys"
          ]
        },
        "target page": {
          "label": "Search protein",
          "page id": "kc_entity_protein",
          "entity parameter": "entity",
          "entity": "protein"
        }
      }
    ]
  },
  "entity": {
    "protein": [
      "protein_info",
      "general_protein_info_function",
      "general_protein_info_go",
      "general_protein_info_pathway",
      "IDG_protein",
      "exRNA_protein"
    ]
  },
  "context": {
    "group": "cfde",
    "contexts": {
      "Experimental biology": [
        "protein_info",
        "general_protein_info_function",
        "general_protein_info_go",
        "general_protein_info_pathway",
        "exRNA_protein"
      ],
      "Genetics": [
        "protein_info",
        "general_protein_info_function",
        "general_protein_info_go",
        "general_protein_info_pathway",
        "exRNA_protein"
      ],
      "Drug development": [
        "protein_info",
        "general_protein_info_function",
        "general_protein_info_go",
        "general_protein_info_pathway",
        "exRNA_protein"
      ]
    }
  },
  "tab groups": [
    {
      "label": "Protein information",
      "group id": "protein_info",
      "required parameters to display": [
        {
          "entity": "protein"
        }
      ],
      "sections": [
        {
          "section": "general_protein_info_function",
          "label": "Protein function"
        },
        {
          "section": "general_protein_info_go",
          "label": "Protein annotations"
        },
        {
          "section": "general_protein_info_pathway",
          "label": "Pathway annotations"
        }
      ]
    }
  ],
  "sections": [
    {
      "section id": "general_protein_info_function",
      "header": "general_protein_info_function",
      "required parameters to display": [
        {
          "entity": "protein"
        }
      ],
      "data point": {
        "type": "api",
        "parameters": [
          "protein"
        ],
        "parameters type": "replace",
        "url": "https://rest.uniprot.org/uniprotkb/search?limit=1&query=(gene_exact:$protein)+AND+(organism_id:9606)+AND+(reviewed:true)&format:json&fields=cc_function",
        "data type": "json",
        "data wrapper": [
          "results",
          0,
          "comments",
          0,
          "texts",
          0
        ]
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Evidences",
            "raw field": "evidences"
          },
          {
            "type": "raw",
            "field name": "Function",
            "raw field": "value"
          }
        ],
        "rows as info cards": {
          "key": "Evidences"
        },
        "top rows": [
          "Function"
        ],
        "column formatting": {}
      }
    },
    {
      "section id": "general_protein_info_go",
      "header": "general_protein_info_go",
      "required parameters to display": [
        {
          "entity": "protein"
        }
      ],
      "data point": {
        "type": "api",
        "parameters": [
          "protein"
        ],
        "parameters type": "replace",
        "url": "https://mygene.info/v3/query?fields=go&q=$protein",
        "data type": "json",
        "data wrapper": [
          "hits"
        ]
      },
      "table format": {
        "data convert": [
          {
            "type": "data to rows",
            "field name": "GO",
            "raw field": "go",
            "group by": [
              "evidence",
              "gocategory",
              "id",
              "pubmed",
              "qualifier",
              "term"
            ]
          },
          {
            "type": "raw",
            "field name": "evidence",
            "raw field": "evidence"
          },
          {
            "type": "raw",
            "field name": "gocategory",
            "raw field": "gocategory"
          },
          {
            "type": "raw",
            "field name": "id",
            "raw field": "id"
          },
          {
            "type": "raw",
            "field name": "pubmed",
            "raw field": "pubmed"
          },
          {
            "type": "raw",
            "field name": "qualifier",
            "raw field": "qualifier"
          },
          {
            "type": "raw",
            "field name": "term",
            "raw field": "term"
          }
        ],
        "top rows": [
          "evidence",
          "gocategory",
          "id",
          "pubmed",
          "qualifier",
          "term"
        ],
        "column formatting": {}
      }
    },
    {
      "section id": "general_protein_info_pathway",
      "header": "general_protein_info_pathway",
      "required parameters to display": [
        {
          "entity": "protein"
        }
      ],
      "data point": {
        "type": "api",
        "parameters": [
          "protein"
        ],
        "parameters type": "replace",
        "url": "https://mygene.info/v3/query?fields=pathway&q=$protein",
        "data type": "json",
        "data wrapper": [
          "hits"
        ]
      },
      "table format": {
        "data convert": [
          {
            "type": "data to rows",
            "field name": "Pathway",
            "raw field": "pathway",
            "group by": [
              "id",
              "name"
            ]
          },
          {
            "type": "raw",
            "field name": "ID",
            "raw field": "id"
          },
          {
            "type": "raw",
            "field name": "Name",
            "raw field": "name"
          },
          {
            "type": "string to array",
            "separate by": ".",
            "take index": 0,
            "field name": "Key",
            "raw field": "_key0"
          }
        ],
        "top rows": [
          "ID",
          "Name",
          "Key"
        ],
        "column formatting": {}
      }
    },
    {
      "section id": "exRNA_protein",
      "header": "exRNA Research Portal ",
      "required parameters to display": [
        {
          "entity": "protein"
        }
      ],
      "data point": {
        "type": "api",
        "url": "https://cfde.hugeampkpnbi.org/api/bio/query/exrna-rbp-counts?q=$protein",
        "parameters": [
          "protein"
        ],
        "parameters type": "replace",
        "data type": "bioindex"
      },
      "filters": [
        {
          "field": "Cell line",
          "label": "Cell line",
          "type": "checkbox"
        },
        {
          "field": "Read count",
          "label": "Read count (>=)",
          "type": "search greater than"
        },
        {
          "field": "Gene",
          "label": "Gene",
          "type": "search",
          "features": [
            "autocomplete"
          ]
        }
      ],
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "RNA binding protein",
            "raw field": "rbp"
          },
          {
            "type": "raw",
            "field name": "Cell line",
            "raw field": "cell_line"
          },
          {
            "type": "raw",
            "field name": "Gene",
            "raw field": "gene_symbol"
          },
          {
            "type": "raw",
            "field name": "Gene id",
            "raw field": "gene_id"
          },
          {
            "type": "raw",
            "field name": "Read count",
            "raw field": "read_count"
          }
        ],
        "top rows": [
          "Gene",
          "Gene id",
          "Cell line",
          "Read count",
          "RNA binding protein"
        ],
        "column formatting": {
          "Gene": {
            "type": [
              "link"
            ],
            "link to": "/research.html?pageid=kc_entity_gene&entity=gene&gene=",
            "new tab": "true"
          }
        }
      },
      "visualizer": {
        "type": "phewas plot",
        "group by": "Cell line",
        "y axis field": "Read count",
        "y ticks decimal point": "0",
        "render by": "Gene",
        "y axis label": "Read count",
        "x axis label": "Gene",
        "beta field": "null",
        "hover content": [
          "Read count"
        ],
        "thresholds": [
          1
        ],
        "label in black": "greater than",
        "plot margin": {
          "left": 150,
          "right": 100,
          "top": 100,
          "bottom": 150,
          "bump": 10
        },
        "height": 200
      }
    },
    {
      "section id": "IDG_protein",
      "header": "IDG: Drug target level classifications",
      "required parameters to display": [
        {
          "entity": "protein"
        }
      ],
      "data point": {
        "type": "graphQl",
        "url": "https://pharos-api.ncats.io/graphql",
        "index": "huge",
        "parameters": [
          "protein"
        ],
        "parameters type": "array",
        "data type": "json",
        "query string": "query targetDetails{\n\n target(q: { sym: \"$parameter\" }) {\n\n name\n\n tdl\n\n fam\n\n sym\n\n description\n\n novelty }}",
        "data wrapper": [
          "data",
          "target"
        ]
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Protein",
            "raw field": "sym"
          },
          {
            "type": "raw",
            "field name": "Name",
            "raw field": "name"
          },
          {
            "type": "raw",
            "field name": "Family",
            "raw field": "fam"
          },
          {
            "type": "raw",
            "field name": "Visit Pharos",
            "raw field": "sym"
          },
          {
            "type": "join multi",
            "field name": "Protein(name)",
            "fields to join": [
              "Protein",
              "Name"
            ],
            "join by": [
              " (",
              ")"
            ]
          },
          {
            "type": "raw",
            "field name": "TDL",
            "raw field": "tdl"
          },
          {
            "type": "raw",
            "field name": "Description",
            "raw field": "description"
          },
          {
            "type": "raw",
            "field name": "Novelty",
            "raw field": "novelty"
          }
        ],
        "top rows": [
          "TDL",
          "Novelty",
          "Protein(name)",
          "Family",
          "Description",
          "Visit Pharos"
        ],
        "column formatting": {
          "TDL": {
            "type": [
              "value in class"
            ]
          },
          "Visit Pharos": {
            "type": [
              "link"
            ],
            "link to": "https://pharos.nih.gov/targets/",
            "new tab": "true",
            "link label": "Open"
          }
        }
      }
    }
  ]
}

pageStyle:
.fixed-header {
position: relative !important;
}
.multi-section-card {
margin-bottom: 20px;
}
#rp_tabs_contents { background: none !important;
  border: none; }

#byor_single_search {
    border: 2px solid #ff6600;
    padding: 20px;
    width: 830px !important;
    margin-left: 0 !important;
}

.byor-single-search-results-wrapper {
    width: 830px !important;
margin-left: 0 !important;
}

span.Tclin > strong {
padding: 0 10px;
    border: solid 2px #337ab7;
    border-radius: 5px;
}
span.Tchem > strong {
padding: 0 10px;
    border: solid 2px #5bc0de;
    border-radius: 5px;
}
span.Tbio > strong {
padding: 0 10px;
    border: solid 2px #ffb259;
    border-radius: 5px;
}
span.Tdark > strong {
padding: 0 10px;
    border: solid 2px #d32f2f;
    border-radius: 5px;
}

.info-card-row {
    margin-bottom: 15px;
}

.info-card-row > .row-key {
    width: 150px; display: inline-block; vertical-align: top;
}

.info-card-row > .row-value {
    width: calc(100% - 150px);  display: inline-block;
}

#byor_single_search { border-color: #ff7f00; }

.dcc-logo-wrapper {
  width: 150px;
    position: absolute;
    left: 0;
    top: 0;
    text-align: center;
}

.row-value.Disease, .row-value.Mondo, .row-value.UniProt, .row-value.DO {
  font-size: 16px;
  line-height: 26px;
}

a { color: #ff7700 !important; }

table.idg-description-table {
  margin-top: 15px;
}

table.idg-description-table td {
  vertical-align: top !important;
}

table.idg-description-table tr.tdl span > strong {
  border-radius: 0 !important;
}


.row-key.image { display: none;}
.row-value.TDL span {
padding: 6px 12px;
    border-radius: 15px;
    margin: 15px;
    font: 500 20px/32px Roboto,Helvetica Neue,sans-serif;
    letter-spacing: normal;
}

#section_IDG_gene td.tdl span.Tbio, #section_IDG_gene td.tdl span.Tchem, #section_IDG_gene td.tdl span.Tclin, #section_IDG_gene td.tdl span.Tdark {
  padding: 6px 12px;
      border-radius: 15px;
      margin: 15px;
      font: 500 20px/32px Roboto,Helvetica Neue,sans-serif;
      letter-spacing: normal;
}

td.tdl {
  vertical-align: top;
}

#section_IDG_disease td.tdl span.Tbio, #section_IDG_disease td.tdl span.Tchem, #section_IDG_disease td.tdl span.Tclin, #section_IDG_disease td.tdl span.Tdark  {
    padding: 2px 12px;
    border-radius: 6px;
    margin: 15px;
    font: 500 13px/14px Roboto,Helvetica Neue,sans-serif;
    letter-spacing: normal;
}

.row-value.TDL span.Tbio, span.Tbio {
    background-color: #ffb259;
    color: #000;
}

.row-value.TDL span.Tclin, span.Tclin {
background-color: #337ab7;
    color: #fff;
}

.row-value.TDL span.Tchem, span.Tchem  {
    background-color: #5bc0de;
    color: #000;
}

.row-value.TDL span.Tdark, span.Tdark {
    background-color: #d32f2f;
    color: #fff;
}

.volcano-plot-content {
text-align: center;
}


.multi-page-search-wrapper { display: none;}

.multi-page-search-wrapper.in-section-ui { display: block;}



/* alex css begin */

.single-search-wrapper {
  padding: 30px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-items: flex-start;
}

.context-btns-wrapper {
  display: flex;
  gap: 10px;
}
.context-btns-wrapper .btn {
  text-wrap: nowrap;
  background: white;
  color: black;
  border: 1px solid #ccc;
}
.context-btns-wrapper .btn.active {
  background: #ff802c !important;
  border: 1px solid #ccc !important;
}
.context-btns-wrapper .btn.btn-warning {
  background: #ccc;
}
.context-btns-wrapper .btn.btn-warning:hover {
  background: #bbb;
}

.dataset-page-header {
  background: none;
  border: 0;
  display: none;
}

.kp-tabs-contents:has(.multi-page-search-wrapper) {
  background: none;
  border: none;
}

.col-md-12:has(.multi-page-search-wrapper) {
  display: flex;
  flex-direction: column;
  gap: 20px;
}
.col-md-12{
  height: fit-content;
}

.tab-ui-wrapper {
  margin: 0;
  background: none;
  border-bottom: 0;
  padding: 0;
}
.tab-content-group {
  background: white;
  border-radius: 0 10px 10px 10px;
  border: 1px solid #ddd;
  padding: 10px 20px;
}
.tab-ui-wrapper .tab-ui-tab {
  border-bottom: 0;
}

button.show-hide-section, button.capture-data {
  display: none;
}

.tab-content-group:has(.multi-section) {
  padding: 10px 0;
}

.multi-section {
  background: white;
  padding: 10px 20px 30px 20px;
  border-radius: 10px;
  border-bottom: 0;
}

.multi-section .section-header {
  padding: 10px 5px;
}
.multi-section .section-header h4 {
  font-size: 22px;
}
.section-header h4 small {
  font-size: 22px !important;
  padding-left: 10px;
    border-left: solid 1px #dddddd;
    margin-left: 5px;
}

.table-total-rows {
  padding-top: 3px;
}
.table-ui-wrapper {
  display: flex;
  align-items: baseline;
  gap: 5px;
}
.tab-ui-wrapper .tab-ui-tab {
  border-bottom: 0;
  color: #5a5a5a;
  background: #ddd;
}
.tab-ui-wrapper .tab-ui-tab:hover {
  color: black;
}
.table-ui-wrapper .number-per-page {
  margin: 0;
  border-radius: 5px;
  border: solid 0.5px #aaa;
}
.convert-2-csv {
  margin: 0;
  border-radius: 5px;
  border: solid 0.5px #aaa;
}

/* tables */
.mbm-plot-content {
  margin: 0 0 20px 0;
}
.research-data-table-wrapper {
  margin: 0 15px;
}
table.research-data-table {
  border: 0 !important;
  text-align: left;
}
.research-data-table tbody:nth-child(odd) {
  background: #f9f9f9;
}

#section_IDG_gene .research-data-table td {
  border: 0 !important;
  padding: 10px 10px;
  vertical-align: top !important;
}

#section_IDG_gene .egl-table-page-ui-wrapper, #section_IDG_gene .table-total-rows, #section_IDG_gene .table-ui-wrapper {
  display: none;
}

#section_IDG_gene .table-wrapper { margin-top: 25px; }

th.Visit.Pharos { width: 120px !important; }

.research-data-table td {
  border: 0 !important;
  padding: 3px 10px;
  line-height: 1.5em;
}
.research-data-table > thead > tr > th {
  border: 0 !important;
  padding: 5px 10px;
}
.research-data-table > thead > tr > th.sortable-th {
  color: black;
}
[class*="cell-weight"] {
  padding-left: 10px;
}
.sortable-th:after {
  content: '';
  background: none;
  width: 10px;
  height: 10px;
  position: absolute;
  margin: 0 0 0 5px;
  bottom: 7px;
  border-right: 5px solid transparent;
  border-left: 5px solid transparent;
  border-top: 5px solid #b4b4b4;
  border-bottom: 5px solid transparent;
}
table.feature-table {
  border-bottom: 3px solid #cccccc;
}
.feature-table > tr > th.feature-title-th {
  background-color: #cccccc !important;
}
table.feature-table tr:nth-child(odd) {
  background: white;
}
table.feature-table th.feature-th-0 {
  background-color: #eeeeee !important;
  border-left: 0 !important;
  padding: 0.3rem 10px;
  border-bottom: 1px solid #ccc !important;
}

#section_general_gene_info_function .row-value.Function {
  font-size: 16px;
  line-height: 26px;
}

/* colors */  
table a {
  color: #ff6600 !important;
}
.show-evidence-btn {
  background: #ffa02c !important;
  border: 0;
}
.show-evidence-btn:hover {
  background: #dc5800 !important;
  color:white !important;
}
.tab-ui-wrapper .tab-ui-tab.loading > .flag {
  color: #ffaa2c;
}
.page-item.active .page-link {
  background-color: #ffa02c;
}
.page-link {
  color: #ff6600;
}

img.dcc-logo {
  width: 100px;
  height: 100px;
  object-fit: contain;
  margin-top: -15px;
}

/* page descriptions */
img.dcc-logo {
  /*position: absolute;
  left: 0;
  top: -10px;*/
}
.page-description-content {
  padding-left: 175px;
  margin: 10px;
  min-height: 70px;
}
.page-description-content h4 {
  font-size: 16px;
  font-weight: bold;
}
.page-description-content p {
  font-size: 14px;
  line-height: normal;
  margin: 0;
}

/* filters, search blocks */
.multi-page-search-wrapper {
  height: fit-content;
}
div.filtering-ui-wrapper {
  border: 0;
  border-radius: 0;
  border-left: 3px solid #ff6600;
  margin: 30px 0 20px;
}
.filtering-ui-wrapper>h4.card-title {
  color: #ff6600;
}
.filtering-ui-wrapper.search-criteria {
  border: 0;
  background: #efefef;
  border-left: 3px solid #34679a;
}
.filtering-ui-wrapper.search-criteria>h4.card-title {
  color: #34679a;
}
.search-fields-wrapper .search-field:empty {
  display: none;
}
.filtering-ui-content .btn-primary {
  background: #ff7f00;
  border: 1px solid transparent;
}
.filtering-ui-content .btn-primary:hover {
  background: #dc5800;
}
.filtering-ui-content .btn-warning {
  background: #ccc;
  border: 1px solid transparent;
}
.filtering-ui-content .btn-primary:hover {
  background: #bbb;
}

/* under development */
.multi-section:has(.info-card .row-value.image) {
  opacity: .5;
}
.details-wrapper:has(.row-value.image) {
  width: 100%;
  display: flex;
  justify-content: center;
}
